window.CHAPTER_DATA["ch07"]={"id": "ch07", "num": 7, "part": "הוצאה", "title": "יציאות השבת (שבת ב.)", "paras": [{"s": "h1", "h": "הוצאה"}, {"s": "h2", "h": "\u003csup class=\"cb\" data-c=\"910\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">1\u003c/sup>\u003cspan class=\"ca\" data-c=\"910\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יציאות השבת (שבת ב.)\u003c/span>"}, {"s": "h3", "h": "א. מתניתין דיציאות השבת"}, {"s": "h7", "h": "מתניתין דיציאות השבת ודינים היוצאים - בגדרי הוצאה דאדם ומקום חפץ"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1500\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">3\u003c/sup>\u003csup class=\"cb\" data-c=\"1499\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">2\u003c/sup>\u003cspan class=\"ca\" data-c=\"1499 1500\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">מתני' (שבת ב.) יציאות השבת שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ. כיצד העני עומד בחוץ ובעל הבית בפנים פשט העני את ידו לפנים ונתן לתוך ידו של בעל הבית או שנטל מתוכה והוציא העני חייב ובעל הבית פטור. פשט בעל הבית את ידו לחוץ ונתן לתוך ידו של עני או שנטל מתוכה והכניס בעל הבית חייב והעני פטור. פשט העני את ידו לפנים ונטל בעל הבית מתוכה או שנתן לתוכה והוציא שניהם פטורין פשט בעל הבית את ידו לחוץ ונטל העני מתוכה או שנתן לתוכה והכניס שניהם פטורין.\u003c/span>"}, {"s": "p", "h": "והנה במתני' דיציאות השבת נתחדשו כמה דינים. א. פטור דשנים שעשאוה, מדלא מצרפים שני המעשים. ב. והעושה מקצתה, ממה שלא מתחייב אחד. ג. עקירת ידו לא הוה עקירה, מפשט העני ידו לפנים ונתן בע\"ה לתוכה ועקר ידו והוציא העני. ד. ידו הנמצאת ברשות אחרת לא נחשבת כרשות שגופו נמצא בה, מהא דהעוקר ממנה ומניח ברשות לא מתחייב, ודנו אי תחשב ככרמלית. ה. עקירה מיד אדם כעקירה מע\"ג מקום ד'."}, {"s": "p", "h": "וכשנמצא לומר יש להבחין כי דינים האמורים במתניתין הם הנוגעים לגדרי הוצאה דאדם, היינו, שייכות אדם למקום חפץ. וכמו מה דלא חשיב מוציא ידו כהוצאה, הוא משום דלא נייח, או משום דגרירא בתר גופו לעומת מוציא כל גופו דחייב לפי שאינו כידו, והיינו, שהרי מקרה ההוצאה בשלושה חלקים. האדם, המקום והחפץ."}, {"s": "h3", "h": "ב. בירור גדר מעשה דאדם במקום חפץ"}, {"s": "h7", "h": "ביאור שייכות עקירה והנחה למעשה הוצאה - משמעות שיהיה חפץ במקום ושיהיה נח לעקירה"}, {"s": "p", "h": "וההקדמה לזה בהקדם ביאור שייכות מעשה האדם בהוצאה במשמעותה כעשייה במקום, ולכאורה נמצאהו בעקירה וההנחה, והנה הרי אין ההוצאה עצמה, היינו, שינוי המקום, העקירה וההנחה, שהרי שאין חסרון בעקירה מה שהחפץ עדיין נמצא במקום. וכן אין נחשב להנחה עצם מה שהוא כבר נמצא במקום, והיינו, שצריך שיעשה האדם את מעשה בהיות החפץ במקום, וכיון שעקירת גופו נחשבת עקירה, הרי שאין חסרון בתפיסת האדם ביחס להגדרת מקום החפץ, והיינו, שצריך שיהיה החפץ במקום שיחשב הוצאה, וצריך שיהיה החפץ נח במקום שיחשב עקירה, וצריך עקירה שיחשב הוצאה דיליה."}, {"s": "h7", "h": "בירור מקום החפץ ביד המוציא - חילוק בין היות אדם במקום אחר להיעדר שם מקום בידו"}, {"s": "p", "h": "והיות חפץ בידי אדם אינו חסרון בהיות החפץ במקום, ולא בהיותו נח. והיות אדם במקום אחר ממקום עקירת והנחת החפץ, אינה חסרון בעקירה, וזה חזינן מחיובי המשנה. אך אם האדם חשוב כאחר מעקירה להנחה, יש חסרון בהוצאה דיליה, ואם גופו אינו במקום אחד עם ידו מהחפץ הרי שאין החפץ במקום גופו, וא\"כ בהכרח שמה שאין ידו נחשבת במקומה הוא חסרון ביד, שאינה נמצאת במקום גופו, שלא ראויה להיחשב כמקום גופו, ובזה היה אפשר לדון למה אינה נחשבת."}, {"s": "p", "h": "והיינו דיש לומר דכיון דבעינן שתיעשה עקירה ע\"י המוציא, הרי שבהיות החפץ ביד המוציא הוא נחשב עקור, וכיון שאין עקירה אלא בדבר נח, בהכרח שאין יד המוציא יכול להיות מקום מנוחת החפץ, שאז לא נשתנה בעקירה דבר."}, {"s": "h7", "h": "סיכום שני גדרי מקום בחפץ - מקום רשות החפץ לעומת מקום חפץ לגבי עקירה ומנוחה"}, {"s": "p", "h": "אלא שהיה לומר דיש למצוא גדרים חלוקים בגדר מקום במעשה הוצאה, ומהן יהיו כמה גדרים במקום חפץ, האחד, מקום רשות החפץ, ובזה נחשב במקום גם כשהוא עקור, והשני, מקום חפץ לגבי עקירה, היינו, חשיבות מקום לגבי חפץ שיהיה שינוי בין אם הוא עקור או לא, וע\"כ יכול להיחשב עקור, אף כשהוא במקום הרשות ממנו נעקר. ואין עקירת החפץ ממקום באותו הגדר עם מקום מנוחת החפץ, דמנוחת החפץ במקום הוא משום שייכותו לרשות, שיחשב העוקר כעוקר מרשות."}, {"s": "h3", "h": "ג. בירור גדר מעשה דאדם ברשויות"}, {"s": "h7", "h": "ראיה מעמוד ט' דאינו מדיני רשות - מקום חפץ ברה\"י נפרד מחלוקת מקומות דהרשות"}, {"s": "p", "h": "והיינו, דחזינן דאיכא שני גדרים במה שחפץ נמצא במקום, מהא דאף בהעברה ברה\"ר איכא לדין הנחה ועקירה במקום ד', הרי שאף ברה\"י דין מקום אינו חלק מדיני רשות, ובהכרח דגדר מקום דרה\"י הוא ביחס לחפץ, דאין דין מקום חפץ כמקום רשות חפץ, דיתכן שיהיה החפץ ברשות ואעפ\"כ אין נחשב במקום הרשות. וזה נוגע לגדר חלוקת מקומות לגבי חפץ, שהרי כל מקום שנח חפץ זה מקומו, ובהכרח שאין זה דין התורה בהוצאה מרשות לרשות אלא שלא להוציא ממקום שהוא ברשות זו למקום שהוא ברשות אחרת."}, {"s": "p", "h": "וכיון דביחס לרשות כל הרשות אחת, להחשיב מקומות שבה כמקומות הרשות, וזה חזינן מעמוד ט' דאף שאינו קרקע הרשות שהרי אינו תופס עשרה לעצמו, אלא גדרו שהוא מקום ברשות, ואף שפחות מכאן הוי כרמלית, היינו, שדין פחות מט' עד ג' אין חסרון בהיות החפץ ברשות, שהרי הרשות תופסת עד עשרה, והיה לחשב גם רוחב המקום, ומהו שפחות מד' הוי מקום פטור, והיה לנו לומר שאין שטח מפחות מג' הוי מקום לעצמו, שהרי הרשות היא בחלל עשרה, וא\"כ יש לחבר מקומות שאין הם תופסים בחלל עשרה כמו בסכך."}, {"s": "h7", "h": "ביאור מקום עמוד ט' כטפל לרה\"ר - מקום החפץ הוי בגדר מוקדם לשם הרשות"}, {"s": "p", "h": "אלא ודאי דאין דין רשות נוגע למקומות, שמקום רשות הוא קודם לרשות, וע\"כ בהכרח דמה שהנחה בעמוד ט' חשיב רה\"ר, אין זה משום שזה נחשב רה\"ר בעצמו, דהא לית ליה גדרי מקום דרה\"ר דטז' אמה וכו', אלא, דהמקום הוא בגדר מוקדם לרשות, ומה שעמוד ט' חשיב רה\"ר אין זה משום שמקומו לעצמו חשיב רשות, וגם אין זה משום דשייך רשות על מקום קטן כזה, אלא אחר דאיכא לרה\"ר מחמת קרקע אחרת, יש לדון דכל מקום שהוא בתוך הרשות יחשב לרה\"ר."}, {"s": "p", "h": "והיינו, שהיה לבאר מהו גדר מקום ד' ברה\"ר, דלכאורה הוא סתירה מיניה, וביה דאם כל ד' חשיב מקום לעצמו, איך יתכן שיתחברו טז' דרה\"ר הרי אין ד' אלו שייכים לד' שלידם, אלא בהכרח שגדר מקום רה\"ר אינו בגדר מקום ד', וא\"כ צ\"ב מהו מקום ד' הנ\"ל, והנראה דהוא מקום חפץ, שאין חשוב חפץ להיקרות ברשות, אם אין הוא נמצא במקום הראוי לחפץ, וזה גדר מקום ד' ברה\"י, שאין זה מגדרי חשיבות דשימוש היחיד, דשימוש היחיד בעי ד' אמות להיחשב מקום ראוי לשימוש, וכמו דין העברה דהיחיד תופס ארבע אמות שלו אף ביחס לזריקה, אלא, היינו, דגדר ד' טפחים ברה\"י אין זה משום דבעינן גדרי שימוש היחיד להחשיב המקום כרה\"י, אלא די בגדרי מקום חפץ."}, {"s": "p", "h": "וא\"כ בהכרח דברה\"ר דבעינן למקום טז' שאינו שייך לגדר מקום חפץ, זה משום שרה\"ר לא חשיבא כך, אלא ע\"י שימוש. וזה כמש\"כ במק\"א. שהרי אין משמעות בתנאי רה\"ר מבכרמלית, מלבד השימוש, ויש ברה\"ר שני גדרים של מקום מקום הרשות ומקום החפץ. והיינו, דמה דאין חייב ע\"י עקירת השני או הנחתו, הוא משום דהוי שנים שעשאוה."}, {"s": "h7", "h": "עקירה  בהכניס יד מחוץ לרשות - יד אדם גרירא בתר גופו לענין הנחה"}, {"s": "p", "h": "אלא שעדיין היה לשאול למה לא נחשב מה שהכניס מבחוץ את החפץ שהיה בידו כעקירה, שהרי היה ברשות והוציאו לרשות אחרת, וזה לא ביארו בגמ' מה שלא נחשב הוצאת ידו חוצה כהנחה ברשות, אף שהדין הוא שמי שנח גופו ברשות חשיב הנחה."}, {"s": "p", "h": "ונראה שזה פשיטא, וזה לכאורה משום שיש לומר שאין זה נחשב הנחה שעדיין גרירא בתר גופו, אבל מי שהניחו בידו חפץ שהגיע מרשות הרי היה ברשות, ומזה דלא חשיב הנחה בידו, הרי דלא נחשב שיצא עדיין מרשות זו ע\"י גרירת גופו, וא\"כ הרי הוא ברשות חוץ. ויש להגדיר את הוצאתו מהמקום כעקירה, ויש לחייבו כשהניח ברשות אחרת."}, {"s": "p", "h": "ויש לחקור במה שפטרוהו, אם הוא חסרון בבמה שהחפץ נחשב נח, דכיון שנעקר ע\"י השני אין הנחתו ביד נחשבת הנחה, שהוא עקור כבר. או שהחסרון בעקירה, שאין עקירת ידו נחשבת לעקירה."}, {"s": "h7", "h": "חקירה בחסרון עקירת גופו מאויר רשות - חסרון הכנסת יד תלוי בגרירת היד אחר הגוף"}, {"s": "p", "h": "ועפ\"ז יש להסתפק במי שהוציא מאוויר רשות ע\"י עקירת גופו, דאם החסרון הוא בגדר החפץ כנח, הרי דאף כאן אין נחשב החפץ לנח, ויהיה פטור, דאין משמעות ביחס למנוחת החפץ מה שאין ידו במקום גופו. אך אם החסרון הוא במה שאין היד נחשבת במקום, הרי שכאן ודאי נחשב במקום, ויתחייב. ופשטו דחייב, ובגדר הבדל גופו מידו אמרו שהוא משום שגופו נח מה שא\"כ ידו, ושאין נחשבת הכנסת ידו עקירה. והיינו, שיש לחקור מה החסרון בעקירת החפץ ע\"י הכנסת ידו מאוויר הרשות לעומת עקירה מיד השני, אם הוא משום שאין נחשב שידו נמצאת במקום ההוא, או משום אם הוא משום שיד השני גרירא בתר מקום שעומד, וכן הוא. וע\"כ הוא שאין גופו וידו במקום אחד לא גרירא, וא\"כ יהיה חייב בעקירת גופו. או שהוא משום שיש חסרון בעצם מה שידו באוויר הרשות בלי שייכות לקרקע הרשות."}, {"s": "h3", "h": "ד. בגדר מקום הנושא שם הוצאה כמעשה במקום"}, {"s": "h7", "h": "חקירה בגדר שם הוצאה במקום - חילוק בין שימוש במקום מסויים לשימוש כללי במקום"}, {"s": "p", "h": "ואחר כל זאת נראה לחקור בגדר שם הוצאה האמור במעשה במקומות, באיזה מגדרי מקום יהיה, ולפי האמור בחילוק גדרי שימוש הנוגעים לשימוש אדם במקום, היינו, שימוש במקום מסויים ע\"י שהוא מקום עצמו, או מקום חפצו, או מקום שימוש בחפצים. וכן שימוש במקום באופן כללי, כמו כל חפץ (היינו נכסים) ע\"י שהוא מלא מחפץ, או הוא עצמו, או משימוש, או ריק במובן שהוא מוכן למילוי הנ\"ל, יחלק גם שם הוצאה."}, {"s": "p", "h": "ויבוא על שני גדרי שימוש אלו באופן שונה, שביחס לשימוש במקום מסויים, כיון שאין שייך להוציא מקום, שם הוצאה הוא ביחס לדבר שנמצא במקום, וכיון שאין שייך על הדבר עצמו שם הוצאה, אלא יציאה יהיה שם הוצאה במה שעושה האדם יציאה לחפץ, וגדר יציאה בחפץ, היינו, התחדשות הימצאותו."}, {"s": "h7", "h": "ביאור החילוק בין מקום כללי למסויים - הבדל משמעות חפץ מצוי במקום לעומת קיים"}, {"s": "p", "h": "וביאורו שאמנם אין לך דבר שאין לו מקום נוכחי המאפשר את קיומו הרגעי, אבל אין זה ביחס למקום מסויים, אלא ביחס למקום באופן כללי, וע\"כ יהיה שייך להעבירו ממקום מסויים למקום מסויים, תוך שמירה על מקום כללי. והעברה הנ\"ל קרויה יציאה, והשמירה קרויה קיום. וזהו הבדל משמעות מצוי לעומת קיים."}, {"s": "p", "h": "וע\"כ ביחס לקיום חפץ יחשבו כל המקומות לקיום אחד, ומציאות שונה והמציאות הנ\"ל ביחס לחפץ עצמו לא תחשב שינוי, אבל יהיו בזה שני גדרי מקום, האחד, שאינו אלא חלק מהמקום הכללי ומעלתו לחפץ הוא הקיום הנ\"ל. והשני הוא, מי שיש בו תוספת גדר של מציאות, והיינו, קיום קבוע. וזה הבדל בין מקום בעל אפשרות מנוחה ובין מקום שאינו, וביחס למקום הוא תוספת גדר מוכנות, היינו, שמקום ללא אפשרות זה אינו נחשב מוכן לחפץ."}, {"s": "p", "h": "וכל זה הוא ביחס לחפץ, או לאדם עצמו, אבל ביחס לשימוש אדם בחפץ יהיה מקומו בעל גדרים נוספים. וכמו שכתבנו זה בשני גדרים עיקריים, והם קביעות, וקירבה. וקביעות הוא, כמו גדר קיום ומציאות ביחס לחפץ, שאין לאדם אחיזה בחפץ שאינו בידו, אם אין לו מקום מנוחה, וזה קביעות שמאפשר המקום. ואין לאדם יכולת שימוש בפועל בחפץ אין הוא קרוב אליו, וזה קירבה שמאפשר המקום. אבל גדר יציאת חפץ אינו אלא ביחס לחלק הראשון, שמשמעות יציאה כאמור מתייחסת למציאות חפץ במקום, וביחס לאדם, זה במה שהוא קבוע."}, {"s": "h7", "h": "משמעות מקום כללי במעשה הוצאה - העברה מרה\"י לרה\"ר כהטבת מצב מקום חפציו של אדם"}, {"s": "p", "h": "וא\"כ יהיה חילוק זה מחלק גדר מעשה הוצאה. דגדרו כמעשה, היינו, במשמעות השפעת דבר על משנהו ביחס ליציאה, הוא שינוי מקום חפץ, אבל ביחס לגדר שימוש אדם במקום כללי, אין שם הוצאה גדר בחפץ, שהרי אין זהות לחפץ ביחס למשמעות המקום עצמו, וביחס למקום המסויים, אם כל המקומות של האדם שווים גם לא יהיה משמעות בזה, והרי זה כמי שמעביר מכלי לכלי בלא צורך. אלא שיתכן שיהיה בזה משמעות אם יהיה לשני המקומות משמעות שונה ביחס לאדם הנוגעת למלא וריקן, והיינו, שאם יהיה משמעות יתירה למילוי וריקנות מקום אחד מאשר משנהו, הרי שיחשב שעושה מעשה בכלל מקומותיו, היינו, מקום באופן כללי (שיוך המקום לאדם האמור פה אינו במובן קנייני, והאדם האמור אינו המסויים הפרטי, אלא ביחס לבני אדם בכלל)."}, {"s": "p", "h": "ובזה יהיה גדר הוצאה כהעברת דבר ממקום אחד למשנהו מחמת חשיבות מליאות או ריקנות, כהכנה למליאות של מקום אחד על משנהו, והוצאה האמורה היא ממקום שיש בו חשיבות זו למקום שאין בו חשיבות זו (או שהיא פחותה יותר). ועשיית שינוי זה הוא מעשה שיש בו עילוי ביחס למקום אדם, היינו, שעד עתה היה המקום רע, ועתה הוא טוב (המקום, היינו, הדבר שמאפשר קיום במובן שימושי אדם). וכמו שיהיו שני כלים, האחד אטום והשני מחורר, ויש בכלי האטום דבר שאין צריך לאטימות ויש לו, או שיתכן לו דברים הצריכים כלי אטום. הרי שמצב שימוש הכלים שלו אינו טוב, וע\"י שמעביר את הדבר לכלי השני הרי שמצב שימוש הכלים שלו הוטב."}, {"s": "p", "h": "וכן בענייננו, שרה\"י היא מקום בעל חשיבות יתר על רה\"ר בנוגע למקום חפצים (שמשתמרת וכו'), ובהיותה ריקה ומוכנה למילוי, והעברה מרה\"י לרה\"ר יש בה הטבת מצב מקומותיו לחפציו, וע\"כ יקרא זה הוצאה, והופכו יקרא הכנסה כי אין העברה מרה\"י לרה\"ר או ההיפך מעשה ברה\"ר, אלא ברה\"י כי אין מעלה ברה\"ר על רה\"י ביחס להינוח חפצים, ומעשים אלו יקראו מוציא מרה\"י לרה\"ר, ומכניס מרה\"ר לרה\"י. וזה הגדר במה שמעשה ההוצאה הוא במקום חפצים כללי."}, {"s": "h7", "h": "גדר הוצאה בשימוש בחפץ עצמו - חילוק בין רה\"י לשמירת חפצים לרה\"ר להעברת חפצים"}, {"s": "p", "h": "אבל אם גדר המעשה הוא ביחס לחפץ, והיינו, שאין גדר מקום החפץ ביחס לשימוש האדם בכלל מקומות חפצים שיש לו להשתמש בהם אלא גדר השימוש הוא בחפץ לבד ואין המקום רק מעלה ביחס לחפץ והחפץ, היינו, במובנו השימושי לאדם, וכמשל מי שיש לו שני כלים וכו', ויש דבר הנצרך לכלי לשומרו, והדבר נמצא בכלי שאינו כן, הרי שיש בהעברת הדבר לכלי הדרוש לו הטבת מצב הדבר, וכן מי שיש לו דבר שרוצה להשתמש בו, והוא נמצא בכלי שאין ראוי לשימוש זה, או שאינו מוכן ללקיחת הדבר לשימוש הנ\"ל שאינו רחב מספיק וכו', יש בהעברת הדבר לכלי הראוי לשימוש זה הטבתו."}, {"s": "p", "h": "וכן בענייננו שרה\"י היא מקום בעל חשיבות שמירת חפצים, ורה\"ר היא מקום בעל חשיבות העברת חפצים. ואמנם כאמור ביחס לגדרי מקום חפצים כללי יש מעלה לרה\"י, אבל ביחס למקום, ולצורך שימוש בחפץ עצמו, הרי שהם שווים, שיש שימוש שדרוש לו מקום כזה, ויש שדרוש לו מקום כזה."}, {"s": "p", "h": "ואמנם ביחס לשימוש המסוים שיש תועלת בהעברתו יש להחשיב זאת כיציאה, אבל אין זה נחשב מעשה הוצאה ביחס למקום שאינו ראוי לשימוש הנ\"ל, שאין במעלה שיש בשימוש בחפץ מסוים להגדיר את המקום שמשמש לשימושים רבים, ושם הוצאה יהיה גדר במעשה שפועל יציאת חפץ אף שלגבי גדר מקום חפצים כללי יש להחשיבו כהכנסה."}, {"s": "h3", "h": "ה. בירור בגדרי מעשה הוצאה כמלאכה"}, {"s": "h7", "h": "בירור לישנא דיציאות השבת במתניתין – יציאות כרשויות וכעקירות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1503\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">6\u003c/sup>\u003csup class=\"cb\" data-c=\"1502\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">5\u003c/sup>\u003csup class=\"cb\" data-c=\"1501\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">4\u003c/sup>\u003cspan class=\"ca\" data-c=\"1501 1502 1503\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">הנה פשטות לשון יציאות האמור במתני' איירי אחפץ, דהמעשה קרוי הוצאה כמו והוציאו אותו, אבל יציאה הוא במה שיוצא, וכדאמרו בפי אמה אי בתר יציאה אזלינן ושם, היינו, יציאה דהחפץ (וזה ניחא לפירוש רש\"י באתי לידי חיוב חטאת דאיירי אעקירות אבל לרבותיו דאיירי אפשיטת יד צ\"ב וי\"ל דאיירי אשעה שהניחו בה כבר שיש לקרותו יציאה. אבל זה קשה שאחר שהניחו כבר לא יבוא לידי חיוב חטאת. וצ\"ע).\u003c/span>"}, {"s": "p", "h": "והנה לישנא דמתני' יציאות דשבת צ\"ב, דאי כרבא דרשויות קתני ניחא, שביאורו סוגי רשויות, ובזה שייך למתני רשויות של שבת, (ואין להקשות דרבא ס\"ל דרשות שבת כרשות גיטין, דהכא איירי בסוגי הרשות ולא בחילוק הרשות עצמה) אבל אם יציאות קתני מהו דנקט יציאות השבת, וכי תני קשירות השבת וכו', ועוד דהרי כלל בזה חיובי ופטורי, ומה שייך לומר על פטורי שבת שהם של שבת."}, {"s": "p", "h": "והנה בגמ' אמרו דכל עקירת דבר ממקומו הוצאה קרי ליה, ולרש\"י דאיירי אעקירות קראום יציאות אפילו בלא יציאה לרשות אחרת, וצ\"ל דעקירה אפילו בלא הנחה ברשות אחרת חשיב יציאה לגבי חפץ. ואף שלא נאסרה אלא הוצאתו מרשות אחת לרשות אחרת, חשיב יציאה ממקום לגבי חפץ. ובפשטות ביאור מה שלא נאסר זה הוא משום שבאותה הרשות הוי מקום אחד (וכמו שאמרו כוליה כד\"א) והרי הניחו בחזרה באותו המקום, ולא עבד מידי, אבל עצם המעשה דעקירת חפץ הוא תחילת המעשה האסור, ויבואר בזה לשון יציאות השבת, במיעוט וריבוי בחיוב ובפטור."}, {"s": "h7", "h": "הקושי בפשיטות פטור מרה\"י לרה\"י - גדר דמוציא מרה\"י לרה\"י לא עביד מידי"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1504\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">7\u003c/sup>\u003cspan class=\"ca\" data-c=\"1504\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">והנה בגמ' לקמן (מט:) אמרו ואתם לא תוציאו מרה\"י לרה\"י והקשו שם מרה\"י לרה\"י מאי קא עביד, ותרצו דהיינו דרך רה\"ר, ופרש\"י דאוויר שבין עגלות היה רה\"ר וקא עביד מעשה. ולא נתבאר מאי פשיטותיה דהמוציא מרה\"י לרה\"י לא עביד מידי דהא הכא איירי אפילו הם חלוקים במחיצה, ואפילו איכא ביניהם כרמלית (ואצ\"ל בשתי דיוטאות, ובגמ' (ב\"ב נו.) אמרו לגבי רה\"ר (ולפר\"ח הוא לגבי רה\"י) דרשויות שבת כרשויות גיטין, ואפילו פיסלא חשיב לחילוק רשויות), והרי עכ\"פ מוציא מרשות לרשות.\u003c/span>"}, {"s": "p", "h": "ואמנם מבואר בכמה מקומות דאין חייבים בזה, אבל קשה לומר דסמכו אדינים האמורים בשאר מסכתא דלשון דמאי קא עביד לא משמע כן, ועוד דהא מהתם ילפינן לעיקר מלאכות דשבת, ומשמע בכל מקום דאי הוה במשכן היה נאסר, ועוד מנא לן פשיטות דבמה דאיכא רה\"ר ביניהם קא עביד מעשה, ואי במשכן הוציאו מרה\"י לרה\"ר ומרה\"י לרה\"י אית לן מיניה."}, {"s": "p", "h": "ומכל זה משמע דפשיטא להו בסברא דהמוציא מרה\"י לרה\"י לא קעביד מידי, ובאמת שזה מוכרח דהא ודאי היה בעבודת המשכן גם הוצאה מרה\"י לרה\"י שקודם שפורק המשכן הוציאו בני קהת את הארון מלפנים, ומינייהו ילפינן לקמן לדין הוצאה. וסברא זו צ\"ב."}, {"s": "h7", "h": "בירור בחיוב הושטה בדיוטא אחת - טעם חילוק אורך רה\"ר מרוחבה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1505\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">8\u003c/sup>\u003cspan class=\"ca\" data-c=\"1505\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">והנה בגדר הושטה דדיוטא אחת ובשונה משתי דיוטאות, כתב רש\"י שדיוטא אחת היא לאורך רה\"ר, ומשמע שזה גדר מה שיש לחלק לענין חיוב, דהנה שם אמרו דילפינן הכנסה מהוצאה מסברא, וצ\"ב מאי איכא באורך רה\"ר יותר מברוחבה, והנה בפשטות אין דין הושטה תולדה דהעברה ד\"א ברה\"ר (היינו דזה חשיב הוצאה משום העברה דרה\"ר דאית ביה) שלא מצאנו שיהיה צורך בהפרש ד\"א ביניהם, וגם לגבי ד\"א ודאי ליכא מעליותא דאורך ארוחב, (ועוד דאי הוה משום לתא דהעברה ד\"א אמאי בעי להלכתא גמירי לה בהעברה).\u003c/span>"}, {"s": "p", "h": "והמשתמע מזה הוא דע\"י דאיכא הפסק דרה\"ר שני רה\"י חשיבי שתי רשויות, אבל אין נראה דבזה ודאי יותר מסתבר שיהיה אורך רה\"ר חולק דמסגי בהדיא ובקעי בה ואיתא ביותר בשתי דיוטאות, ובכלל קשה לומר שיש בהפסק רה\"ר חילוק יותר לגבי שתי רה\"י מבהפסק כרמלית ומחיצות."}, {"s": "p", "h": "וגם אין לומר דחשיב חילוק לגבי רה\"ר המסויימת דאיכא ביניהם, דהא גזוזטראות הוו גבוהות י' וקימ\"ל דאין רה\"ר שולטת באוויר למעלה מי'. ועוד דלפ\"ז נצטרך לומר שהוא גדר ברשויות עצמם שחשובה רה\"י זו כחלוקה מחברתה, והנה ברש\"י פירש דאיירי דהוו בעליה אחת, ולכאורה משמע דאיירי אפילו בדמצי להביאו דרך גג או פתח (וגם לא מצאנו חילוקי דינים אפילו בשתי גזוזטראות דבית אחד שאינו חלוק בתוכו), וקשה לומר דחשיבי חלוקים יותר מסתם שתי רה\"י משום חילוק שיש ביניהם בצד אחד, וגם קשה לומר שיהיה גדר זה בעגלות שהרי אין מצבם קבוע כך להגדיר חלוקה בעצם."}, {"s": "h3", "h": "ו. בירור בגדרי חלקי מלאכת הוצאה"}, {"s": "h7", "h": "חילוקי גדרים בחלקי מעשה דהוצאה כמלאכה – גדר הנעשה בחפץ ביציאתו מרשות לרשות"}, {"s": "p", "h": "ובהקדם ביאור זה מה שמצאנו חילוקי גדרים שיש למצוא בחלקי מעשה דהוצאה ובגדרו להיחשב מלאכה, והנה כבר כתבנו שעיקר גדר מלאכה יותר משאר איסורי שביתה הוא בחשיבות המעשה, ואין זה גדר של סוג עשייה דאדם (היינו באומץ כוח או יחוד כוונה או חכמת העשייה) אלא סוג עשייה חשובה בדבר, וע\"כ חשיבות עשיית דאדם את המעשה הוא במה שכך נעשה דבר זה. ובמלאכת הוצאה, היינו, שהדבר שבו נעשה המעשה הוא הדבר היוצא, ושיעור גרוגרת הוא בדבר היוצא."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1506\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">9\u003c/sup>\u003cspan class=\"ca\" data-c=\"1506\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">אבל לא נתבאר איזה מעשה נעשה בדבר במה שהוא יוצא מרשות לרשות, והיינו, דאי הוה איסור רק בהכנסה ולא בהוצאה, שפיר היה לומר שיש עילוי בדבר הנמצא ברה\"י ממה שהיה ברה\"ר, שהוא שמור, וכן להיפך שיש בזה חשיבות לטלטולו, אבל כיון שהוא אסור בשני האופנים אין לומר שיש כאן גדר עילוי מצבו (ובפרט לדעת ר' יוחנן בירו' דבהוציא חצי שיעור והכניסו מתחייב), וגם אין לומר דהוי עילוי בעצם היות לחפץ מקום דהא בעינן לעקירה כהנחה ולא די בהנחה לבד ומוכח שאין זה איסור בעצם הימצאותו במקום החדש, היינו, היות לחפץ מקום ומנוחה הוי גדר עילוי של מצב החפץ שלזה אין צורך בעקירה (ובפרט לסברא דגמ' דאמר' ודילמא הנחה הוא דלא בעי אבל עקירה וכו'), ואי בעי הרי הוי כדבר שאין מתקיים, ועוד דלפ\"ז היה מסתבר לומר שלא תהיה הנחה במקום פטור הפסק מעשה, וכ\"ש שלא היה נאסר זריקה לאש ולפי כלב, וגם אין ביאור בכל זה די להעברה ד\"א וכו'.\u003c/span>"}, {"s": "h7", "h": "גדר מלאכת הוצאה בשינוי מצב דבר - חשיבות המעשה בהתאמת מקום השימוש ולא ביצירה חדשה"}, {"s": "p", "h": "ויש להקדים מה שכבר ביארנו במק\"א שגדר מלאכת הוצאה שונה מרוב מלאכות שהיא מלאכת שינוי (וכבר ביארנו שם מדוע אינה מלאכת עלוי דבר כבורר ומבשל וכו', וזה פשוט שאינה מלאכת חידוש דבר ככותב וכו' (היינו יצירת חפץ מונח במקום) ואפשר דסותר וקורע ומוחק ומכבה גם חשיבי מלאכת שינוי ועוד יבואר), וביארנו שאמנם ברור יותר חשיבות מעשה שיש בו חידוש תוצאה ומה שיש בתוצאה להחשיב המעשה, אבל אין זה גדר מלאכת מחשבת שהוא גדר מעשה ולא תוצאה (דלא אמר הכתוב לא יהיה אלא לא תעשה)."}, {"s": "p", "h": "וכן במלאכת הוצאה שאף שאין דבר חדש בחפץ חשוב מלאכה, והיינו, שאף שמקודם המלאכה ולאחר שנעשית ישנו לחפץ המונח במקום, ומצוי ברשות חשובה, ולא נשתנה זה ע\"י מעשה ההוצאה, אבל עיקר המעשה הוא מעשה חשוב, ששינוי מקום חפץ מכאן לכאן הוא צורך חשוב (בבחינת מוכנותו לשימוש התלוי במקום וכו') ויש במעשה זה מחשבה הוי מלאכת מחשבת, ושינוי מצב מוכנותו לשימוש התלוי במקום הוא הרי במקום עצמו, ובהיות מקומו של החפץ בו."}, {"s": "p", "h": "וא\"כ יהיה עיקר חשיבות מעשה הוצאה במה שהיא מעשה במקומות כחפצים ולא במקום חפץ, והמשל בזה מי שיש לו שני כלים והוא מחשב באיזה מהן ראוי להשתמש (ולא כמי שיש לו חפץ והוא מחשב למצוא לו כלי), וע\"כ לא יהיה גדר חשיבות מעשה ההוצאה במה שהוא שינוי מקום חפץ מסוים, אלא בשינוי מצב שימוש ברשויות באופן כללי, אלא שזה אינו שייך אלא בשינוי מקום חפץ מסוים."}, {"s": "h3", "h": "ז. בירור כנ\"ל לגבי רשויות"}, {"s": "h7", "h": "יסוד חילוק רה\"י מרה\"ר בצורך האדם - יעוד המקום ומוכנותו לעומת זהות המקום לשימוש"}, {"s": "p", "h": "ועוד יש לנו להקדים בזה מה שכבר ביארנו במק\"א שיש לחלק גדר מקום לשתי משמעויות, ושתיהם נובעות מצורך האדם במקום, האחד, הוא יעוד המקום ומוכנותו לשימוש האדם וממילא לחפצים המונחים בו, והשני הוא זהות המקום ביחס לשימוש אדם בחפצים מבחינת יעודו לשימוש, והיינו, שיש לאדם צורך במקום לשימוש ונוח, וצורך לשימוש במקום לחפציו לשימוש והינוח, וע\"כ יהיה משמעות במקום ביחס להנחת חפציו, וגם יהיה משמעות במקום ביחס לשימוש בחפציו באותו מקום, וצורך שיש לאדם בחפציו הוא הקובע חשיבות החפץ, וצורך במקום להנחת חפציו הוא הקובע חשיבות המקום, ומשמעות שימוש האדם במקום הוא המבדיל בין סוגי המקום (כמו רה\"י שהוא מקום תשמיש ורה\"ר הוא מקום הילוך), ומשמעות שימוש דאדם בחפץ במקום הוא המבדיל בין חלקי מקומות אף שהם מאותו הסוג (כמו ד\"א שהוא תפיסת שימוש מקום אחד דאדם וממילא גם לגבי חפץ), אבל יש ומקום מסוג אחד לא יחולק למקומות שימוש כמו מקום מסוג אחר משום שזה מיועד לשימוש שיש לו משמעות חלוקה בתוכו וזה אין לו משמעות חלוקה בתוכו."}, {"s": "p", "h": "ובזה יהיה חילוק הגדר בין מקום רשות הרבים למקום רשות היחיד, דכיון שחשיבות רשות היחיד היא במה שהיא מקום תשמיש ליחיד, וחשיבותה יותר משאר מקומות הוא במה שהיא מוגדרת וחלוקה, הרי שעיקר גדרה הוא במקומה החלוק, וע\"כ לא יהיה ברשויות היחיד החלוקות זו מזו גדר הוצאה או העברה, שהרי זה עצם מהותה של הרשות שהיא חלוקה, ואין בזה שום מעשה."}, {"s": "h7", "h": "העדר הוצאה מרה\"י לרה\"י בעצמה - חילוק מרה\"ר המשמשת להילוך תמיד לכלל הרבים"}, {"s": "p", "h": "וביתר ביאור לפי האמור לעיל דכיון שמעשה הוצאה הוא מעשה במקומות כחפצים (היינו שם רשות), הרי דחשיב כאילו נמצאים לפניו כל הרשויות, ואין במעשה דהוצאה התחדשות הרשות, שאין חילוק מקום של רשות היחיד גדר זהות, אלא איכות שאין חילוקה ממקום אלא מאדם, ואמנם אין זה מקום אחד, אך אין איסור הוצאה ממקום למקום אלא מרשות לרשות, ויש לחשב את חלוקת הרשות ביחס לאדם ולא ביחס לחפץ מסוים, שהרי ביחס לחפץ זה ומקומו אין מעשה הוצאה דבר אחד אלא שנים, ואין זה ממינו של זה, וכיון שכל רשויות היחיד הם דבר אחד באיכותם כתשמיש היחיד, אין בחלוקתם לחלקם."}, {"s": "p", "h": "אבל רשות הרבים גדרה הוא במה שהיא משמשת להילוך תמיד לרבים, ולא בחלוקתה משאר מקומות. ואין מקומה חלק מגדרי הרשות שהרי אינה מיועדת לשימוש מקומי, וע\"כ אף שהיא רשות אחת ובעינן לה שיעור ט\"ז אמה יהיה חשיבות לגבי הוצאה אפילו בהעברה בתוכה, כי אין מקומה אחד ביחס לחפצים הנמצאים בה."}, {"s": "h3", "h": "ח. ביאור גדר מעשה הוצאה בהושטה"}, {"s": "h7", "h": "מושיט מרה\"י לרה\"י דרך רה\"ר - הפסק רשות הרבים יש בו לגלות שינוי מקום החפץ"}, {"s": "p", "h": "ובזה יש לבאר גדר הושטה מרה\"י לרה\"י דרך רה\"ר, שאמנם אין יציאה מרה\"י לרה\"י שינוי מצב ביחס לחפץ, שכיון שרה\"י מיועדת לשימוש קבוע, ועיקר מוכנותה היא מה שהיא משמשת את האדם, הרי שעיקר משמעות מקום חפץ ברה\"י הוא חלל שימוש ולא שימוש האדם בו, וע\"כ לא יהיה משמעות לגבי חלוקת מקומות בה, והיא רשות אחת. אבל אם יהיה בין שני רה\"י הפסק רה\"ר הרי שאין חלוקתם יחסית רק לסוג שימוש שלהם, אלא גם ביחס לשימוש שיש ברשות שביניהם אם יהיה משמעות בזה לגבי מעשה ההוצאה, ואף שודאי אין משמעות זו שייכת לגבי מצב החפץ בהיותו מונח בהם, כי אין בזה משמעות ביחס לכל רשות לעצמה, אבל יהיה משמעות זו שייכת באם יתחברו שני מצבים אלה ע\"י מעשה ההוצאה, היינו, שינוי מקומו של חפץ בזמן השינוי עצמו, וביחס למשמעות העקירה מכאן וההנחה מכאן."}, {"s": "p", "h": "והיינו, שכמו שאמרנו הרי גדר מלאכת הוצאה חלוקה למקומות ורשויות וגדר עקירה לבדה והנחה לבדה הוא גדר במקום חפץ (מקום ד\"ט), אך אין שייכות בין שניהם אלא ביחס לרשויות, והיינו, שבעקירת חפץ ממקום כבר נתבטלה ממנו משמעות מונח, והרי הנחה במקום אחר היא כיצירת דבר חדש, ואין משמעות חפץ מונח לעצמו חשובה מלאכה אלא משום שעקירתו והנחתו הם ברשויות, ובהם עיקר משמעות חפץ הוא במה שמשמש לאדם, כל מעשה ההוצאה חשוב לאחד, היינו, עקירת חפץ ממקומו עם משמעות הוצאתו מרשות לרשות, שזהו גדר בחפץ וביחס לשימושו ולא למקומו ואינה נאבדת בעקירתו מהנחה כאן וכן אחר הנחתו שם (ויש בזה לבאר דעת רש\"י דהחשיב עקירה דבעל הבית והנחה בידו הפשוטה של העני כיציאה) וזה משמעות שינוי האמור."}, {"s": "h7", "h": "חילוק בין מושיט לזורק - הוצאה דרך רה\"ר שייכת רק במעשה אחד המחבר שתי רשויות"}, {"s": "p", "h": "וע\"כ במושיט שהוא מעשה אחד יהיה גדר מה שאין עקירתו היתה להנחה ברה\"ר שביניהם, ובהנחתו שלא נעשתה דרך רה\"ר הנ\"ל, ואמנם ביחס למקומו של חפץ אין זה גדר שינוי אלא שמירת הסוג (דהרי הוא אפילו ביותר מי'), אבל ביחס לרשות הרי שהיא חלוקה מרשות הראשונה בגדר חילוק מקום, כיון שיש ברה\"ר משמעות חלוקת מקומות בתוכה, וע\"כ אין ללמוד זורק ממושיט, שיש לומר שאין משמעות זו שייכות רק משום היחס בין שתי הרשויות שנעשה ע\"י מעשה אחד ארוך, אבל לולי כן אין משמעות חלוקת מקומות האמורה תחשב ביחס למקום החפץ, וכדאמרן שאין זה נחשב שינוי ביחס לגדר מקום חפץ דרה\"י (ויש לדמות זה לפיזור המותר לעומת בירור האסור אף שנברר בפיזורו שאין משמעות בברירה אלא ביחס לתערובת)."}, {"s": "h7", "h": "ביאור בחיוב הושטה בדיוטא אחת - אורך רשות הרבים מגדיר חלוקת מקומות ולא רוחבה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1507\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">10\u003c/sup>\u003cspan class=\"ca\" data-c=\"1507\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">ומעתה יש למצוא דרך להבנת החילוק בין אורך לרוחב רה\"ר, שאמנם ביחס לחילוק מקומות אין משמעות ברוחב יותר מבאורך, אך ביחס לחילוק רשות דאית ביה הרי שאורך רה\"ר הוא אחד ולא רוחבו, וע\"כ יהיה משמעות ביותר לגבי חלוקת רה\"י השונה ממנה (וכן יש לבאר מה שכתב רש\"י בפיסלא שהוא לרוחב רה\"ר ולא לאורכו כי אין משמעות חילוק בזה יותר משכבר יש, וכן יבואר מה שכתב דהוא לכל רוחב רה\"ר, והיינו, שהרי יש ברה\"ר לאחד כל רוחבה ולא יועיל פיסלא ד\"ט או ד\"א דכיון שאורכה אחד מצידי הפיסלא ורוחבה אחד לעניינו אין זה חילוק (וזה דווקא בפיסלא שהוא גדר בשימוש וכו' ואכמ\"ל)) ובמק\"א פירשתי יותר.\u003c/span>"}, {"s": "h3", "h": "ט. ביאור מתניתין דיציאות השבת והגמ' לפמשנ\"ת"}, {"s": "h7", "h": "ביאור לישנא דמתני' לרב פפא – משמעות יציאות אמקום חפץ ביחס לרשות ולא לשימושו"}, {"s": "p", "h": "ובהקדם כל זה יבואר לשון המשנה לדעת רב פפא וכך הוא, שלשון יציאות הוא ביחס לגדר הוצאה דרה\"י ורה\"ר שגדר השינוי בהם הוא בסוג יעוד מקומות הרשות (היינו מקום הרשות שמובנו החלוק שמשמש לרבים הרבה והוא מקומות ביחס למונח ולשיונח בו), והוא גדר במקום חפץ ולא בשימוש חפץ, וע\"כ שייך למיתני ביה לשון יציאות ממקום ולמקום שהוא מלשון עשיית מציאות (מצוי) במקום, והוא משמעות מקום חפץ ביחס לסוג הרשות, שהמקום עצמו אין הוא תלוי בהימצאות דבר, והוא מקום איתו ובלתו, אך ביחס להיותו חלק מרשות הרי יעוד וכו'."}, {"s": "h7", "h": "בהכרח הגמ' דאיירי אף אהכנסה – משמעות הוצאה הכוללת עקירה והנחה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1508\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">11\u003c/sup>\u003cspan class=\"ca\" data-c=\"1508\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">וזה ביאור הגמ' שהביאה הוכחה ממשנה דאבות מלאכות דהמוציא מרשות לרשות דע\"כ איירי גם בהכנסה. ולא נתבאר פשר הדברים, דאדרבה הא התם איירי באבות מלאכות, והכנסה תולדה היא, וע\"כ לא איירי בהכנסה, ומאי הוכחה יש כאן. ודברי הגמ' בשבועות דאמר מרשות לרשות סתם לא נתבאר, ועוד מהו שנצרכנו לזה אחר דקתני יציאות ומפרש הכנסה.\u003c/span>"}, {"s": "p", "h": "ולפי האמור יהיה ביאורו, דעיקר קושיית הגמרא הוא בשבועות דאיירי בחיובי וכלל הכנסה בלשון הוצאה, דכיון דאיירי במעשה שלם דעקירה והנחה, אף דהוה הוצאה מרה\"ר, אין לקרות לשון המעשה כולו דחיובי בלשון הוצאה (היינו דאף שמצאנו לשון יציאה חוצה, ובהכרח שיציאה זו היא ביחס למקום שהיה ולא לכלל המעשה, דאל\"כ חוצה הוי יתור, כיון שכתב יציאות ופירש מעשה שלם לא משמע ביה הכנסה, אבל במתניתין דידן הרי כלל פטורי דחד צד, ובהכרח דיציאות אף בהכנסה איירי), ואמרו דהא לגבי אבות מלאכות שאין לפרש בהם אלא לחיובי כתב המוציא מרשות לרשות, ולשון מרשות לרשות הוא יתור שהרי כולה מתני' בלשון העושה כתיבא, והעושה ודאי הוי מרשות לרשות (ולא כתב השוחט בהמה או הקוצר וכו'), ובהכרח דכתב כן משום הכנסה דכלל ביה, וקרא למעביר חפץ מרשות לרשות מוציא. ומוכרח שקורא לכלל העשיה ע\"ש התחלה שלה, והיינו, עקירה ויציאה, היינו, ממקום החפץ ולא מהרשות, ואחר כן אמר דהכי מוכח מלישנא דמתני', והיינו, דאיך שלא נפרש שתיים שהן וכו' ואף אם נאמר דאיירי רק ההוצאות, והכנסה כדי נסבה לא היה לו למתני הכנסה ברישא, דהוא מעשה הוצאה, ובהכרח דאיירי אעקירת חפץ ממקומו, ובזה אין נפק\"מ בין הוצאה להכנסה."}, {"s": "h7", "h": "ביאור לישנא דיציאות במתניתין - שם כולל של מעשה בהימצאות החפץ ולא שינוי רשות לבד"}, {"s": "p", "h": "ומעתה יש לבאר לישנא דיציאות השבת, והיינו, דלישנא דיצא לעומת כנס אכן איירי אעקירת חפץ ממקומו, אבל קריאת המעשה כולו הוא כמו שביארנו, שגדר יציאה הוא לשון כולל של עשיית מעשה בהימצאותו (וכדכתיב ואם יצא יצא וכו' ומצא אותו וגו' והמצוי לכל נמצא לזה). ואם לישנא דמוציא הוא ביחס למשמעותו השימושית של החפץ ברשות, לישנא דיציאה הוא ביחס למשמעות המקומית והוא מעשה דיוצא (מלרע זכר דתוצא), והוא כולל כל המעשה."}, {"s": "p", "h": "ותראה כי בזה יהיה גדר שינוי מקום חפץ בלי גדר הרשות (אף שהוא כוללם כאמור אין בזה צורך לגבי הוצאה והכנסה), וכיון שכן יש משמעות למקום המוציא יותר מרשויות שיוצא, וע\"כ לא פירט הוצאה והכנסה שע\"י הנחה, כי בזה יבואר יותר שאין גדר החיוב תלוי במשמעות העברה ביחס לעושה אלא רק ביחס לחפץ, אבל יהיה משמעות כזו ביחס לזה עוקר וזה מניח, והיינו, בפטורי דאתי לידי חיוב חטאת."}, {"s": "p", "h": "ויבואר לישנא דשבת האמורה, והיינו, דלא איירי אדין שבת, אלא איום שבת, שהרי לא נאסרו מלאכות ביום השבת אלא משום דהוי מלאכתך, היינו, מה שיש בהם משמעות מלאכה לאדם, וזה גדר שבת לה'. וכאילו אמר גדר יציאות, היינו, מעשה האסור שהוא משום שבת, והיינו, מלאכה לאדם, שתים שהן ארבע. ובזה יבואר השמטת זריקה והושטה והעברה ברה\"ר וכו'. ועזב את ותם עת ופסק עט."}, {"s": "h3", "h": "י. סדר הדינים וחלוקת אופני מעשה הוצאה לפמשנ\"ת"}, {"s": "h7", "h": "חילוק ילפותא דהוצאה מהעברה - הוצאה תליא בסוג המקום והעברה תליא בזהות המקום"}, {"s": "p", "h": "ואחר כל זאת יבואר סדר חלוקת הדינים הנושאים דמלאכת הוצאה כך, שהנה כמש\"כ דיש למצוא חילוק בין הוצאה להעברה, שהוצאה שינוי במקום הנוגע לסוג המקום, ומה שגדר המקום המוקדם משפיע על חפצים המונחים בו. והעברה היא בנוגע לזהות המקום, ומה שחילוקי מקומות משפיעים על שינוי השימוש של חפץ ומקום, וכיון שגדר שינוי דהוצאה תלוי בהגדרת המקום לעצמו, יבואר מה דלא בעו ילפותא להכנסה, שאין בה פחות מהוצאה בשינוי סוג המקום (ואפשר אכן דאי כתב רחמנא הוצאה בגוונא דהכנסה, היה לומר שאין המלאכה שינוי אלא עילוי שיש בחפץ שמור וכו', אבל אחר דאיירי בהוצאה פשוט דאיירי בשינוי, שאין רה\"י מועטת שימוש מרה\"ר שאינה אטומה וחתומה)."}, {"s": "p", "h": "וכן לא בעי קרא לזריקה מרשות לרשות, דכיון שעיקר השינוי הוא באיכות המקום, הרי שגדר ההוצאה הוא בהיות החפץ במקומות אלו, ומעשה הוצאה נוגע רק לעשייה אחת של השינוי הנ\"ל, ואין בזריקה פחות מהולכה ביד או ברגל לגבי זה."}, {"s": "p", "h": "אבל בהעברה כיון שגדר השינוי הוא לא במקום עצמו, שאין המקום מחולק מחבירו אלא ביחס לחפץ, והיות החפץ במקום מגדירה את המקום כשונה ממקום שלידו (ד\"א), הרי שיהיה צורך ללימוד על העברה לבד, ועל זריקה לבד, ואין ללמוד זה מזה. דאי כתב העברה לא הייתי לומד זריקה מיניה, דכיון שגדר השינוי הוא במקום חפץ, היה לומר שאם אין הוא מניח בידים במקום החדש, אין זה נחשב שהמקום משוייך לחפץ באותו האופן שהיה המקום הקודם, ואין זה שינוי אלא קלקול שעתה הרי הוא כבלי מקום (וטעם יש בזה שהרי אין זכות להניח חפצים במקום רה\"ר אם אין הם חלק משימוש אדם בו). ואי כתב זריקה לא הייתי לומד העברה מיניה שהיה לומר שדווקא בזריקה שהאדם נותר במקום הקודם יש משמעות אחידה לשני המקומות, שקודם היה קרוב ועתה נתרחק, ויש משמעות במעשה בצירוף שני המקרים לגדר שינוי."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1509\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">12\u003c/sup>\u003cspan class=\"ca\" data-c=\"1509\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">וע\"כ אמרו דבעי הילכתא לתרוויהו אף דלא בעו מידי לזריקה מרשות לרשות (וגם לא היה במשכן, ומה דכתב רש\"י בסוגיא דכוורת דילפי ממחטין, היינו, עיקר דין זריקה דהוי דרך הוצאה ממקום למקום, אבל לא בעי לזריקה מרשות לרשות דתהוי במשכן, וכן נראה דבזה חלק ר\"ע דיליף זורק ממושיט).\u003c/span>"}, {"s": "h7", "h": "ביאור חילוק מעשה דמושיט וזורק - מושיט מגדיר בפועל מעבר דרך רה\"ר משא\"כ זריקה"}, {"s": "p", "h": "ולפמשנ\"ת דהושטה הוא גדר העברה ממקום למקום ולא הוצאה מרשות לרשות, וכיון דמשמע דגדר העברה דאית ביה (היינו דהוה עשיית מלאכה) הוא מסברא, צ\"ל שהיא נלמדת מהילכתא דהעברה, ולא נצרכה להיותה במשכן אלא משום שגדר העברה דאית בה הוא מחמת המעשה (היינו שאין משמעות שינוי מרה\"י זה לחבירו ,אלא משום המעשה שבו שהוא דרך רה\"ר), יש צורך ללמוד דמעשה דהושטה (ואפילו למעלה מי') חשיב להגדיר שהחפץ עבר דרך רה\"ר. וזה ביאור מה שלא למדו זריקה מיניה, דבהושטה איהו עביד מה שהחפץ שט מעל מקום רה\"ר, ויש בזה להגדיר השינוי האמור. אבל בזריקה אינו."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1510\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">13\u003c/sup>\u003cspan class=\"ca\" data-c=\"1510\" style=\"--a:#0d9488;--abg:rgba(13,148,136,0.1)\">(ועפ\"ז יש לבאר דברי רש\"י דבריש הזורק משמע דמה שהיו הקרשים כבדים ולא היה ניתן לזורקם הוא סיבה למעט זריקה, ובריש מסכתין בביאור מה דיליף ר\"ע זורק ממושיט גם כתב כן, ולכאורה הוא לא נצרך אחר שר\"ע יליף מיניה זורק, ולפי הנ\"ל יתבארו דבריו הק' דאכן יש למצוא כאן סיבה לשניהם. היינו, דאמנם מחמת כובד הקרשים ברור דלא הוה זריקה במשכן, ואי לא דמי לכאורה ליתא לזריקה מקור דחשיב הוצאה. אבל לר\"ע דדמי ליה אין זה גילוי כאמור אלא סיבה למילף אלא דלא הוה, דבאמת אף ע\"י זריקה הוה הוצאה, ומה לא עשו כן במשכן הוא רק מחמת כובד הקרשים. ודו\"ק.\u003c/span>"}, {"s": "p", "h": "והנה בסוגיא דריש הזורק בעו לקרא דמלאכת הוצאה, ובפשטות משמע דהכי הוא בכל המלאכות, וילפינן לה ממעשה רוקם חרש וכו', וכן הוא לגבי זריקה ד\"א דבעו למילף לה מאורגי ותופרי יריעות, ואי הוה ידיענן להוצאה מינייהו, היינו, שהיה להם צורך בזה, לא בעינן לקרא. אלא כיון דלא בעי לאיזה ממלאכות המשכן בעינן לקרא דהוה בכלל במשכן (והנה אף דודאי בעו להוציא ולהכניס, אבל לענין מילף בעינן שיהיה זה חלק ממעשה המלאכה עצמה). וגם העברה ילפינן ממשא בני קהת, ולא בעו לקרא אלא לדין ד\"א ברה\"ר. ויתבאר בע\"ה)."}, {"s": "h3", "h": "יא. עוד בעניין שם יציאה"}, {"s": "h7", "h": "בירור גדר שם יציאה במקומות - ראיה מהילוך כהן בהיכל דאינו ממקום גדור לפתוח"}, {"s": "p", "h": "והנה בעיקר שם יציאה יש לדון אם אינו שייך אלא דווקא ממקום גדור למקום פתוח או יתכן אף בממקום למקום, ובזה יש אי שייכא בכל שינוי מקום או דווקא במקומות מסויימים, וכן באי תליא במקום שממנו נעקר או במקום שיונח בו, או דתליא בתרוויהו וכו'."}, {"s": "p", "h": "והנה מצאנו בהליכת כהן ממקום הזאה דבין המזבח הפנימי לפרוכת למקום דבין המזבח הפנימי לפתח ההיכל, דאע\"ג דתרוויהו הוי בהיכל, קראתו תורה יציאה (ובגמ' זבחים (פג.) נסתפקו אי חשיב נכנס (לחוזר ומכניס מבין המזבח הפנימי ולפתח לבין המזבח ולפרוכת)), ומשמע שאין שם יציאה דווקא ממקום גדור למקום פתוח."}, {"s": "p", "h": "אבל הנה תניא בפסחים (פה:) לא תוציא מן הבית מן הבשר חוצה אין לי אלא מבית לבית מחבורה לחבורה מנין ת''ל חוצה חוץ לאכילתו. ע\"כ. ומזה יש להוכיח שאין הוצאה למקום פתוח דווקא, דהא ילפי מלישנא דתוציא אפילו מבית לבית. אבל יש לדקדק דבעי קרא דחוצה לאסור הוצאה מחבורה לחבורה בבית אחד, ומשמע דפשטות לישנא דתוציא בלא חוצה אינו אלא ממקום גדור, ויקשה למה לא ילפי לה מיציאה דכהן, דחשיב יציאה אפילו במקום אחד, ואפשר דלא לה התם אלא משום דכתיב מן הבית, אבל שם יציאה סתם איתא אפילו במקום אחד."}, {"s": "h7", "h": "מוציא בשר פסח מחבורה לחבורה - דין עקירה והנחה מלא תוציא בבית אחד"}, {"s": "p", "h": "עוד שם (פסחים פה:) א''ר אמי המוציא בשר פסח מחבורה לחבורה אינו חייב עד שיניח הוצאה כתיב ביה כשבת מה שבת עד דעבד עקירה והנחה אף ה''נ עד דעבד עקירה והנחה. ע\"כ. ויש לדקדק אמאי לא ילפי מקדשים דכוותה שחשיב יציאה דפסול יוצא אף בלא הנחה."}, {"s": "p", "h": "והנ\"ל דלא דמי יציאה להוצאה, דשם יציאה תלוי רק בדבר היוצא ולא במעשה דהוצאתו, וע\"כ בפסול יוצא שאין גדר איסורו משום מעשה הוצאה דהמוציא אלא משום יציאת הדבר, התם לא בעינן הנחה, אבל הוצאה שהיא מעשה דאדם לא הוה אלא בעקירה והנחה. וכיון דלשון הפסוק הוא לא תוציא בהוצאה דאדם, יש לדמותו להוצאה דשבת ולא ליוצא דקדשים, וכן משמע מרש\"י שם (ד\"ה היו) דכתב דטומאת המוציאים לשריפה בעי הנחה, משום דכתיב ביה והוציא את הפר."}, {"s": "h7", "h": "דקדוק לישנא דרש\"י בבשר פסח - צורך עקירה והנחה מעיקר שם הוצאה ולא מקדשים"}, {"s": "p", "h": "והנה יש לדקדק בדברי רש\"י התם (ד\"ה דעבד) דכתב דבשבת בעינן עקירה והנחה דעד שיניח לא נגמרה מלאכה, וגבי שבת וכל חיובי חטאת כתיב בעשותה בעושה את כולה ולא בעושה מקצתה (שבת דף צב:) והאי נמי אע''ג דלאו בר חטאת הוא הוצאה כי התם בעינן. ע\"כ. ומשמע דדין עקירה והנחה הוא מעיקר המלאכה, ולא חשיב הוצאה בלאו הכי."}, {"s": "p", "h": "ונראה ביאור דבריו כך, דלגבי שבת שאיסורה נאמרה בלשון שלא לעשות מלאכה, והרי דמלאכה האמורה חשיבא לעצמה, ולא כמעשה, שלא נאמר לא תוציא, וע\"כ אין חשיבותה תלויה בעושה עצמו, ואם נעשית המלאכה, היינו, עד ההנחה, אף דאיהו לא עבד אלא חלקה, חשיב עושה מלאכה, והוה מחייב, אי לאו מיעוטא דבעשותה, אבל בפסח אין הוצאה גדר לעצמו, אלא היא מעשה האיסור, ולא יהיה שם הוצאה אמעשה עד תומו, וע\"כ עד שלא יניח לא חשוב שהוציא."}, {"s": "h7", "h": "בירור סוגיית אוויר מזבח בזבחים - הנחת גופו כהנחת קרבן וספק בהולך בין כבש למזבח"}, {"s": "p", "h": "בגמ' זבחים (פז:) בעו אי אוויר מזבח הוי כמזבח לענין פסולין דאם עלו לא ירדו, ואמרו שם (פח.) דאי נקט להו לא מבעי, היינו, כשעומד ע\"ג מזבח ואוחזן בידו, משום אוויר מזבח כמזבח, וכתב רש\"י (ד\"ה אמר) דזה משום דהא גברא בראש מזבח קאי, והנחת גופו בראש מזבח כהנחת קרבן דמי, ואמרו דבעיא בתלנהו בקנה באוויר מזבח, ומשמע דאי קאי אארעא ונקט להו אף אי הוה אוויר מזבח כמזבח, הנחת גופו אארעא כהנחת קרבן אארעא דעזרה ולא אאוויר קרבן, והנה בגמ' שם לעיל מיניה דנו דאי אוויר מזבח לאו כמזבח, מה יועיל דעלו אכבש, דכיון דאוויר יש בין מזבח ולכבש, הוה כירדו, ואין העלאת כבש מועילה להקטירם, כיון דלא מצי להביאם למזבח, ואמרו דכשגוררם בזמן שרובם בכבש חשוב בכבש, וכשרובם במזבח חשובים במזבח."}, {"s": "p", "h": "ויש להסתפק אי בעינן לה גם בנקט להו בידיה, והיינו, דמה דאמר רש\"י דהנחת גופו הוי הנחה, אי הוה דווקא כשעומד, או אפילו כשהולך, ואי נימא דאף כשהולך הוי הנחת גופו צ\"ב מאי שנא משבת."}, {"s": "p", "h": "וכן יש להסתפק אי בזמן שהולך מעל אוויר שבין כבש ולמזבח חשיב כמונח אכבש ומזבח, או אף בזה בעינן לסברא דרובו לכבש וכו', ואי נימא דבעינן, יש לדון אי מהני ביה (וראיתי יש אומרים דאפילו גופו מנח אארעא וידו באוויר מזבח חשוב כהנחת קרבן ע\"ג מזבח ולא הוי ירוד, וצ\"ב מאי שנא משבת דלא בעי אביי למימר (ג:) אלא דלא הוה כנמצא במקום עמידתו, אבל כמקום אווירו מאן דכר שמיה)."}, {"s": "h7", "h": "היוצא מאוויר מזבח להנחת גופו - החשבת מקום החפץ כנמצא במקום עמידת גופו"}, {"s": "p", "h": "ומ\"מ לכאורה יש להוכיח מכאן דמה דאמרינן הנחת גופו כהנחת חפץ, אין ביאורו רק לגבי מה שנח, והיינו, שהיה לומר, דמה שחשוב החפץ ברשות הוא משום עצמו, ולא בעו להחשיב הנחת גופו כהנחת חפץ אלא לגבי מעשה הנחה, ולא לגבי מקומו, והכא משמע דאף אי אין אוויר מזבח כמזבח (שאינו מקום מזבח כלל), בהנחת גופו חשוב הקרבן נמצא במזבח, והיינו, לגבי מקומו דיש להחשיב היותו ביד מי שמונח אקרקע דמזבח כהיותו אקרקע דמזבח (ואין לומר דודאי אוויר דמזבח חשיב כמזבח, ולא דנו בזה אלא משום שדבר הנמצא באוויר אינו חשוב כדבר קבוע, ובעי שינוח ע\"ג מזבח, ולזה יועיל הנחת גופו דהא לגבי העלאתו מכבש למזבח תרצו בנגרר, והרי נגרר ודאי לא חשוב קבוע במקומו, דהא בשבת מחייב עליה אף שהמוציא חצי חפץ ואחר כך הוציא שאר החפץ פטור, כי דבר הנגרר אינו חשוב כנח)."}, {"s": "h7", "h": "הנשמע מהנ\"ל בגדר הנחה דשבת – דין הנחה במקום ולא בעמידת חפץ"}, {"s": "p", "h": "ואם אכן גם לגבי שבת יש לומר דאין גדר הנחה רק לגבי קביעות דנח, אלא גם מה דחשיב ברשות כנמצא על מקום עמידת מי שאוחזו (היינו, לגבי מקום מסויים ברשות) דהא לגבי רשות עצמה אמר אביי דידו אינה נזרקת אחר גופו לגמרי שתהיה כרשות שגופו נמצא בה."}, {"s": "p", "h": "והיינו, דאף דודאי עמידת גופו כעמידת חפץ, אבל אין דין הנחה גדר רק במה שהחפץ עומד, אלא בעינן שיהיה הנחה, ואין הנחה אלא במקום, והנחה במקום, היינו, ביחס לשאר מקומות, והיה להסתפק אי הנחת גופו הוה הנחה במקום החפץ, או במקום גופו דאי הוה הנחה במקום החפץ, אין עצירת הילוכו הנחה אלא הפסקה סתם (ולא הוי אפילו כשתי כוחות באדם, דלא עקר או עצר החפץ מהמשך הילוכו, אלא רק הפסיק את סיבת הילוכו), ונצטרך לומר דכיון שהניח גופו גם חפץ המונח על גופו חשוב כמונח, וכמו מוציא חפץ בתוך כלי דבהנחת הכלי חשוב הנחה לגבי חפץ (ואין זה תלוי בספיקא דרבא באגוז וכלי דהתם מניח אכלי, אבל אם יניח הכלי עם האגוז, פשיטא דלא הוה הנחה יותר מכלי לבד), אבל אי נימא דהוה הנחה במקום גופו, והיינו, שחשוב החפץ מונח היכן שגופו מונח ואין ידו מקום החפץ ובהילוכו, כיון שאין גופו מונח גם חפץ אינו מונח, ובהנחת גופו חשוב כאילו הניח החפץ במקום גופו, וזה הנחה מעלייתא."}], "comments": [{"id": "910", "n": 1, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-113 | סוג: חיבור עצמאי | מקור: קבצים ערוכים להטמעה / ביאורי רש\"י (פרק א חלק ו' במסמך הבדיקה)\u003c/p>\u003cp>כותרת מוצעת בסגנון הכותרות שבקובץ: ביאורי רש\"י למסכת שבת - לחי, פי תקרה, תקנת עירובין והנחת עירוב (אותיות 12-16, שבת יא.-מט.)\u003c/p>\u003cp>חלק שני של הלקסיקון: ביאורי רש\"י בדיני לחי, פי תקרה, תקנת עירובין, הנחת עירוב והושטה. מקום השילוב: בסמוך לסוגיות ההוצאה והרשויות.\u003c/p>\u003cp>הצעת קטע קישור בפתיחת הקטע: ולביאור הסוגיות יסייעו הביאורים הבאים בדברי רש\"י:\u003c/p>\u003cp>נוסח הקטע בשלימותו:\u003c/p>\u003cp>12. לחי משום מחיצה (שבת יא:)\u003c/p>\u003cp>\\&gt; רש\"י (שבת יא:): *\"תוך הפתח. של מבוי דהיינו רחב האסקופה: צריך לחי אחר להתירו. שהלחי המתיר את המבוי סתמיה נגד האסקופה וזקוף עליה וקסבר אסור להשתמש נגד הלחי אלא מחודו הפנימי ולפנים הוי היכר המחיצה.\"\u003c/p>\u003cp>ביאור: ומשמע דאף למאן דאמר משום מחיצה, הוא משום היכר מחיצה.\u003c/p>\u003cp>13. מקום ד' טפחים ופי תקרה (שבת יב.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת יב.): *\"פתח נעול. והדלת שוקף בפני האסקופה הפנימית וכל האסקופה חוץ לדלת כלחוץ ואפילו תחת הקורה דכיון דנסתם המבוי בטלה לה קורה וליכא למימר יורד וסותם דכל מחיצה שאין בין חלל המחיצות ד' אינן מחיצות ולא שייכא בהו תורת גוד אחית ולהכי לא אוקמא באסקופת בית דסתם בית פתח שלו יש לו משקוף מלמעלה ונמצא עובי הפתח כולו מקורה ואפילו פתח נעול אמרינן יורד וסותם שהרי יש בחלל עביו ד' מן הדלת לסתימת פי התקרה וה''ה דמצי לאוקמא כולו מקורה אלא שאין ברחב עביו ד' אלא משום דסתם עובי החומה אינו פחות מד'.\"\u003c/p>\u003cp>ביאור: ואף שכתב לעיל בכוורת שאינה גבוהה שבעה ומחצה דאמרינן לבוד לגבי מחיצות אף שאין שם מקום ד', היינו ששם אין גדר המחיצה למשהו אלא לעצמה; אך כאן גדר המחיצה הוא לרשות ומשום היקף, ואין היקף אלא למקום, ואין מקום אלא בד' טפחים.\u003c/p>\u003cp>14. אוזניים לתורה ותקנת עירובין (שבת יד:)\u003c/p>\u003cp>\\&gt; רש\"י (שבת יד:): *\"שלמה גזר. דכתיב (קהלת יב) ואיזן וחקר שעשה אזנים לתורה כלומר סייג והרחקה ככפיפה זו שנוטלין אותה באזנים ואין נוגעין בה: עירובין. אזנים להוצאת שבת שאסור להוציא מרשותו לרשות חבירו ואע''פ ששניהם רה''י.\"\u003c/p>\u003cp>ביאור: ומשמע דתרתי איכא הכא: חדא, דגם ע\"י עירובין אין מגיעים לגעת בכלי עצמו, היינו שלא יבואו לעבור על איסור הוצאה; ועוד, שע\"י זה אוחזים בכלי עצמו, היינו שיאחזו ישראל במצוות. דהכי איתא בפרש\"י בעירובין, שע\"י דין עירובין מחזיקים במצוות דאיסור הוצאה בשבת, שנח לאחוז בכלי שיש לו בית יד משאין לו, והיינו שיש באיסור הוצאה גדר דשב ואל תעשה, ואם היו נמנעים כלל ממה שדומה להוצאה היה די בכך, אלא שלא היה זה בגדרי המצווה ורק הרחקה; אך ע\"י מצוות עירובין הרי הם אוחזים במצווה ביותר, דכיון דצריכי למעבד עירוב להוצאת חצרות הרי דהוי האי מצווה בקום ועשה, ויש בזה לחזק המצווה.\u003c/p>\u003cp>15. הנחת עירוב וקניין שביתה (שבת כד.)\u003c/p>\u003cp>\\&gt; רש\"י (שבת כד.): *\"בעירובי תחומין. תיקון מעליא דאסמכוה רבנן תחומין אקראי ואפי' למאן דאמר תחומין דרבנן כדאמרינן בעירובין (דף נא.) ילפינן מקום ממקום ומקום מניסה כו' אבל עירובי חצרות חומרא בעלמא הוא ולא מיקרי שביתה מעלייתא וספקא דבין השמשות שפיר דמי.\"\u003c/p>\u003cp>ביאור: והיינו דהכא איירי אדין דהנחת עירוב, ואף דגם עירובי תחומין קיימא לן דהוא מדרבנן, עכ\"פ קניית שביתה דתחומין במקום הנחת עירוב הוא תיקון חשוב, שנחשב שזה מקומו וכדילפינן וכו'. אך מה דע\"י הנחת עירוב חצרות חשיב שהוא דר בבית שמונח בו עירוב, אין בזה שביתה חשובה, שאין בזה גדר שזה מקומו שלו, אלא לגבי מה שהחצר מיוחדת לבית זה לעניין צירוף בני החצר שזכותם בחצר מעורבת יחד, אך עדיין חשיב מקומם בביתם שהוא מקום לינה ופיתא, ואית להם רשות בית שלהם ואוסרים ומבטלין.\u003c/p>\u003cp>(והכי מוכח מהא דלא מועיל ביטול לחד, וכתב רש\"י שהוא משום דאדעתא דהאי חולקא לא עירב; ואם ע\"י עירוב נעשה שהוא גר בבית שמונח בו עירוב ועי\"ז הותר שאין רק בית אחד, מאי נפק\"מ שלא עירב אדעת זה, כיון שהוא גר רק בבית שמונח בו עירוב אין לו לאסור. ואכמ\"ל).\u003c/p>\u003cp>אבל אין זה אלא לגבי דין קניית מקום שע\"י הנחת עירוב; אבל כיון שדין תחומין הוא דרבנן יועיל אפילו בבין השמשות, דהאי סברא ליכא אלא לגבי הנחת עירוב שהיא מעשה הקנייה שאין לעשותה בזמן ספק כיון שיש לה משמעות קנייה, אבל לגבי מה שמועילה הקנייה כיון שהונח הונח.\u003c/p>\u003cp>וכן כתב לגבי קטן המניח את העירוב דלא מועיל בעירובי תחומין אבל מועיל בעירובי חצרות: דכיון שהוא רק לעירובי רשותייהו, כיון שמונח בבית ממילא מעירבי, שאין זה גדר ששינה מקום שביתתו אלא שרשות בית בחצר שלו מעורבת עם כל בני חצר; אבל בעירובי תחומין צריך לשנות את מקומו מביתו למקום הנחת עירוב, וזה ע\"י שקונה שם מקום שביתה, וקטן אינו אלים לקנות מקום שביתה, והיינו שאף שלגבי מה שנחשב מקום פיתא ולינה הרי זה כמו בעירובי חצרות, אבל כיון שאין די שיהיה מונח שם העירוב אלא צריך שיקנה שביתה ע\"י הנחת עירוב, אין זה מועיל בקטן.\u003c/p>\u003cp>ואין לזה שייכות עם מה דסבר שמואל עירוב משום קניין, שזה גדר מה שעושה העירוב המונח שם, ואין זה גדר הנחה עצמה דזה אף לשמואל גדר דדירה, כמו שמוכח התם דכולה הכא דיירי ובית שמניחים בו את העירוב אין צריך ליתן; אלא שנחלקו מה נעשה ע\"י עירוב זה שמתירם: דלדעת שמואל ע\"י הנחת עירוב קונים חלק בבית, ולדעת רבה ע\"י זה חשיב שהוא דר בבית. ואין קטן האמור שם כקטן דהכא, דקטן דהכא לא עשה רק איסוף של העירוב, אבל אחר שהונח גדר הקנייה הוא במה שפת שלו מונח בבית זה הרי שיש לו חלק בבית זה; אבל קטן דהתם איירי שעושה אותו שליח שע\"י הנחה זו יקנה הקטן ויקנה לו, ולא שע\"י דאית ליה אוכל שם קונה, אבל אם אינו רק גובה לכולם אין בזה רק מעשה קוף.\u003c/p>\u003cp>16. מושיט מעגלה לעגלה (שבת מט:)\u003c/p>\u003cp>\\&gt; רש\"י (שבת מט:): *\"קרקע. רשות הרבים: עגלה. רשות היחיד שגבוהה י' ורחבה ד': דרך רשות הרבים. דאויר שבין העגלות רשות הרבים.\"\u003c/p>\u003cp>ביאור: וצ\"ב, דהנה הרי דין זה הוא מדין מושיט, והרי מושיט הוי אפילו יותר מעשרה, וליכא למאן דס\"ל קלוטה ביותר מעשרה, דהא לא אוויר רשות הרבים הוא, דאין תופסת אווירה אלא עד עשרה, כדאמר בפ\"ק. ובהכרח דכוונתו דהעגלות עצמן חלוקות, משום דאוויר שבין העגלות הוי רשות הרבים; אבל זה קשה שהרי אין העגלות רשות היחיד אלא בגובהן אך תחתיהן לא, ואף אי נימא דהוי רשות הרבים מקורה אין הוא מוציא משם.\u003c/p>\u003cp>אלא היינו כוונתו: שכיון שמוציא דרך אוויר יש גדר בזה שהוא דרך הקרקע, ואף שאין זה עניין לכלי שמוציא כדאמרן, לגבי חילוק הרשויות הוי עניין, דכיון שאוויר שעובר בו הכלי הוא של קרקע (היינו מה שהיה אם היה נח באוויר זה), הרי שיש משמעות לעגלות ביחס לקרקע שתחתיהן, וכיון שכן הרי שהם חלוקים ע\"י דאיכא רשות הרבים ביניהם, וחשיבי שתי רשויות חלוקות לגבי הוצאה זו (ואף שיהיו מחוברים באיזה אופן ע\"י פתח, וכמו בשתי גזוזטראות דלא מצאנו שיפטר ע\"י פתח שיש בין הבתים). ואף דתחתיהם הוי רשות הרבים מקורה, אין זה חיסרון ברה\"ר עצמה למעט ט\"ז שלה או לחלקה, אלא רק לגבי מי שמטלטל תחתיה יותר מארבע אמות או לגבי המוציא לה.\u003c/p>", "t": "essay", "sv": 3}, {"id": "1499", "n": 2, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-525 | סוג: הקדמה וזיהוי | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>הגרסה העדכנית פותחת סוגיה זו בהקדמה ובזיהוי נקודת המוצא:\u003c/p>\u003cp>זיהוי הסוגיה ונקודת המוצא:\u003c/p>\u003cp>הסוגיה המרכזית: שבת ב. - ד. (משנת יציאות השבת: פשט העני ידו לפנים, פשט בעל הבית לחוץ; פטור זה עוקר וזה מניח, העושה מקצתה; ידו אינה כרשות גופו; עקירה מיד אדם כמע\"ג מקום ד').\u003c/p>\u003cp>הקושי שהניע את המחבר: מה היחס בין מעשה האדם בהוצאה לחפץ ולמקום הרשות, ומדוע עקירת ידו לבדה אינה עקירה (דלא נייח) ואילו עקירת גופו נחשבת עקירה לכו\"ע.\u003c/p>\u003cp>מוצע לשלב את ההקדמה בפתח הסוגיה, לפני הפסקה הראשונה.\u003c/p>", "t": "intro", "sv": 2}, {"id": "1500", "n": 3, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-587 | סוג: פסקת פתיחה | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>הגרסה העדכנית פותחת סוגיה זו בפסקת פתיחה הכוללת מראי מקומות:\u003c/p>\u003cp>במשנה הפותחת את מסכת שבת (ב.) שנינו: יציאות השבת שתים שהן ארבע בפנים ושתים שהן ארבע בחוץ, ומתוכה נתבארו יסודות דיני הוצאה, עקירה והנחה, ידו של אדם שאינה מקום מנוחה לחפץ (שם ג:), ופטור שנים שעשאוה (שם ג.). ובירור גדרים אלו מעמיד את מקום האדם כנושא החפץ ביחס לרשויות.\u003c/p>\u003cp>מוצע לשלב פסקה זו כפסקה הפותחת של הסוגיה.\u003c/p>", "t": "opening", "sv": 2}, {"id": "1501", "n": 4, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-526 | סוג: הקדמה וזיהוי | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>הגרסה העדכנית פותחת סוגיה זו בהקדמה ובזיהוי נקודת המוצא:\u003c/p>\u003cp>זיהוי הסוגיה ונקודת המוצא:\u003c/p>\u003cp>הסוגיה המרכזית: שבת ב. - ג:, מט:, צח:; ב\"ב נה: - נו. (משנת יציאות השבת, פירוש 'אתי לידי חיוב חטאת' ברש\"י, מרה\"י לרה\"י מאי קא עביד, רשויות שבת כרשויות גיטין, הושטה בדיוטא אחת לאורך רה\"ר).\u003c/p>\u003cp>הקושי שהניע את המחבר: מדוע נקטה המשנה לשון 'יציאות' על הכנסה ועל פטורים, מדוע פשיטא לגמרא (מט ע\\\"ב) דהמוציא מרה\"י לרה\"י לא עביד מידי, ומה מבדיל בין אורך רה\"ר לרוחבה בחיוב הושטה.\u003c/p>\u003cp>מוצע לשלב את ההקדמה בפתח הסוגיה, לפני הפסקה הראשונה.\u003c/p>", "t": "intro", "sv": 2}, {"id": "1502", "n": 5, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-588 | סוג: פסקת פתיחה | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>הגרסה העדכנית פותחת סוגיה זו בפסקת פתיחה הכוללת מראי מקומות:\u003c/p>\u003cp>הנה בלשון המשנה בריש מכילתין 'יציאות השבת שתים שהן ארבע' הקשו בגמ' (ב:) ובראשונים (רש\"י ב. ד\"ה יציאות, ד\"ה אתי לידי; תוס' שם ד\"ה יציאות) מאי טעמא תני 'יציאות' אפטורי ובהכנסה, וכן יש לברר פשיטות הגמ' לקמן (מט:) דמרה\"י לרה\"י לא עביד מידי, לעומת חיוב הושטה מדיוטא לדיוטא לאורך רה\"ר (צח:).\u003c/p>\u003cp>מוצע לשלב פסקה זו כפסקה הפותחת של הסוגיה.\u003c/p>", "t": "opening", "sv": 2}, {"id": "1503", "n": 6, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-722 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(שם) — לאחר: \"בתר יציאה אזלינן ו\"\u003c/p>", "t": "refs", "sv": 1}, {"id": "1504", "n": 7, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-723 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(שם ד\"ה והא) — לאחר: \"דרך רה\"ר, ופרש\"י\"\u003c/p>\u003cp>(שבת צח:) — לאחר: \"(ואצ\"ל בשתי דיוטאות\"\u003c/p>\u003cp>שם — לאחר: \"תוציאו מרה\"י לרה\"י והקשו\"\u003c/p>", "t": "refs", "sv": 1}, {"id": "1505", "n": 8, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-724 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(שבת צח:) — לאחר: \"ובשונה משתי דיוטאות\"\u003c/p>\u003cp>(שם ד\"ה בדיוטא) — לאחר: \"צח:), כתב רש\"י\"\u003c/p>", "t": "refs", "sv": 1}, {"id": "1506", "n": 9, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-725 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(שבת פ\"א ה\"א) — לאחר: \"ר' יוחנן בירו'\"\u003c/p>", "t": "refs", "sv": 1}, {"id": "1507", "n": 10, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-726 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(רש\"י ב\"ב נה: ד\"ה בפיסלא) — לאחר: \"רה\"ר ולא לאורכו\"\u003c/p>", "t": "refs", "sv": 1}, {"id": "1508", "n": 11, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-727 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(שבת עג.) — לאחר: \"דהמוציא מרשות לרשות\"\u003c/p>", "t": "refs", "sv": 1}, {"id": "1509", "n": 12, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-728 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(שבת ח. ד\"ה רחבה; צז:) — לאחר: \"דכוורת דילפי ממחטין\"\u003c/p>", "t": "refs", "sv": 1}, {"id": "1510", "n": 13, "a": "מגיב – מראי מקומות והקדמות", "d": "2026-11-18", "h": "\u003cp>מש-729 | סוג: מראי מקומות | מקור: הגרסה העדכנית של החיבורים (מראי מקומות והקדמות וזיהוי)\u003c/p>\u003cp>בגרסה העדכנית נוספו לפסקה זו מראי מקומות (מוצע לשלבם בגוף הפסקה):\u003c/p>\u003cp>(שבת צו: ד\"ה תולדה) — לאחר: \"רש\"י דבריש הזורק\"\u003c/p>", "t": "refs", "sv": 1}]};
